import { test } from "node:test";
import { fail, say } from "../shared/dojo.ts";
import { topK, wordCount } from "./words.ts";

const show = (o: unknown) => JSON.stringify(o);
const sorted = (o: Record<string, number>) => Object.fromEntries(Object.entries(o).sort(([a], [b]) => a.localeCompare(b)));
/** What is actually wrong with a result, so the hint matches the mistake rather than the test's name. */
const why = (got: Record<string, number>, dflt: string) => {
	const ks = Object.keys(got);
	return ks.includes("") ? "empty" : ks.some((k) => /[A-Z]/.test(k)) ? "case" : ks.some((k) => /[^a-z0-9]/.test(k)) ? "punctuation" : dflt;
};

test("Lv1_Basic", () => {
	const got = sorted(wordCount("the cat saw the hat")), want = {"cat": 1, "hat": 1, "saw": 1, "the": 2};
	if (show(got) !== show(want)) fail(why(got, "wrong_count"), say(`"the cat saw the hat" 的结果应该是 ${show(want)}，实际是 ${show(got)}。`, `For "the cat saw the hat" the result should be ${show(want)}, got ${show(got)}.`));
});

test("Lv1_Case", () => {
	const got = sorted(wordCount("The the THE cat")), want = {"cat": 1, "the": 3};
	if (show(got) !== show(want)) fail(why(got, "case"), say(`"The the THE cat" 里大小写不同的同一个词被分开数了：期望 ${show(want)}，实际 ${show(got)}。`, `In "The the THE cat" the same word in different case was counted separately: expected ${show(want)}, got ${show(got)}.`));
});

test("Lv1_Punctuation", () => {
	const got = sorted(wordCount("Hello, world! Hello.")), want = {"hello": 2, "world": 1};
	if (show(got) !== show(want)) fail(why(got, "punctuation"), say(`"Hello, world! Hello." 的结果里有带标点的词：期望 ${show(want)}，实际 ${show(got)}。`, `For "Hello, world! Hello." some words still carry punctuation: expected ${show(want)}, got ${show(got)}.`));
});

test("Lv1_Empty", () => {
	const got = sorted(wordCount("   ")), want = {};
	if (show(got) !== show(want)) fail(why(got, "empty"), say(`文本 "   " 里没有词，期望结果为空，实际是 ${show(got)}。`, `The text "   " has no words, so the result should be empty; got ${show(got)}.`));
});
